:root {
  --ink: #1a1040;
  --ink-light: #4a3f72;
  --cream: #f7f2e8;
  --gold: #c9a84c;
  --gold-light: #e8d48a;
  --accent: #5b3fa6;
  --accent-muted: #8a6fd4;
  --bar-bg: #1a1040;
  --footer-bg: #2d1f5e;
  --divider-color: #c9a84c;
}

article.ticket {
  width: 476px;
  background-color: var(--cream);
  border: 2px solid var(--gold);
  border-radius: 10px;
  overflow: hidden;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
}

.ticket-header {
  background-color: var(--ink);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-bottom: 2px solid var(--gold);
}

.dome-icon {
  font-size: 22px;
  line-height: 1;
}

.header-text {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.venue {
  color: var(--gold);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.subtitle {
  color: var(--accent-muted);
  font-size: 9px;
  letter-spacing: 1px;
  margin-top: 1px;
}

.ticket-num {
  color: var(--gold-light);
  font-size: 15px;
  font-weight: 700;
  border: 1px solid var(--gold);
  border-radius: 4px;
  padding: 2px 7px;
}

.ticket-body {
  display: flex;
  flex-direction: row;
  flex: 1;
}

.show-info {
  flex: 1;
  padding: 11px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.show-title {
  color: var(--ink);
  font-size: 18px;
  font-weight: 800;
  line-height: 1.2;
  margin: 0;
  letter-spacing: 0.5px;
}

.show-desc {
  color: var(--ink-light);
  font-size: 10px;
  line-height: 1.4;
  margin: 0;
}

.tags {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 2px;
}

.tag {
  background-color: var(--accent);
  color: var(--cream);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 20px;
}

.divider {
  width: 1px;
  background-color: var(--divider-color);
  margin: 10px 0;
  position: relative;
  flex-shrink: 0;
}

.divider::before,
.divider::after {
  content: '';
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 8px;
  height: 8px;
  background-color: var(--cream);
  border: 1px solid var(--gold);
  border-radius: 50%;
}

.divider::before {
  top: -4px;
}

.divider::after {
  bottom: -4px;
}

.details {
  width: 136px;
  padding: 11px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: flex-start;
  flex-shrink: 0;
}

.detail-block {
  display: flex;
  flex-direction: column;
  margin: 0;
  gap: 1px;
}

.detail-label {
  color: var(--accent-muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.detail-value {
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

.barcode {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  height: 28px;
  gap: 2px;
  margin-top: 2px;
  width: 100%;
}

.bar {
  background-color: var(--bar-bg);
  width: 4px;
  border-radius: 1px;
  flex-shrink: 0;
}

.bar.thin {
  width: 2px;
}

.bar.wide {
  width: 6px;
}

.barcode-num {
  color: var(--ink-light);
  font-size: 7px;
  letter-spacing: 1px;
  margin-top: 1px;
}

.ticket-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
  border-top: 2px solid var(--gold);
}

.footer-left {
  color: var(--accent-muted);
  font-size: 10px;
  letter-spacing: 0.5px;
}

.price {
  color: var(--gold);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 1px;
}
